python3 -c 'exec("import time\nfrom math import isqrt\np=55067263\nv=(isqrt(8*p+1)-1)//2\nc=p-v*(v+1)//2\nk=v-c+1\nK=k+1\nB=4*K\nif k!=2:raise SystemExit(2)\ndef step(q,a):\n u=c//B**(2*q+a)%B\n z,r=divmod(u,K)\n return r,z//2,2*(z%2)-1\nif any(step(q,a)!=(1-q,a,1-2*q) for q in (0,1) for a in (0,1)):raise SystemExit(2)\nq=h=0\ntape={}\nprint(\"COSMIC_LOVE\",flush=True)\nwhile True:\n a=tape.get(h,0)\n q,b,d=step(q,a)\n if b:tape[h]=b\n else:tape.pop(h,None)\n h+=d\n time.sleep(.05)\n")'
